import React, { useEffect, useRef, useState, useCallback } from 'react';
import { database } from '../services/firebase';
import { ref, set, push, onValue, onChildAdded, remove, onDisconnect, update } from 'firebase/database';
import {
  RTC_PEER_CONFIG,
  getUserMediaWithFallbackOptions,
  attachStreamToVideo,
  streamHasLiveVideo
} from '../utils/webrtcMedia';
import './MeetingRoom.css';
import PresentationPanel from './PresentationPanel';

function MeetingRoom({
  roomNumber,
  userData,
  currentUser,
  isHost,
  initialMicOn = true,
  initialCameraOn = true,
  waitingUsers = [],
  onAdmitUser,
  onRejectUser,
  onLeave
}) {
  const [status, setStatus] = useState('Pripájam médiá...');
  const [isMicOn, setIsMicOn] = useState(Boolean(initialMicOn));
  const [isCameraOn, setIsCameraOn] = useState(Boolean(initialCameraOn));
  const [hasMicDevice, setHasMicDevice] = useState(true);
  const [hasCameraDevice, setHasCameraDevice] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [remoteParticipants, setRemoteParticipants] = useState([]);
  const [screenSharingBy, setScreenSharingBy] = useState({});
  const [focusedParticipantId, setFocusedParticipantId] = useState(null);
  const [isPinnedView, setIsPinnedView] = useState(false);
  const [leaveNotice, setLeaveNotice] = useState('');
  const [showHostLeaveDialog, setShowHostLeaveDialog] = useState(false);
  const [isLeaving, setIsLeaving] = useState(false);
  const [isWaitingPanelAlert, setIsWaitingPanelAlert] = useState(false);
  // Defaultne sa snažíme zvuk pustiť hneď. Ak prehliadač zablokuje autoplay,
  // prepneme na false a používateľovi sa zobrazí tlačidlo na manuálne zapnutie.
  const [isRemoteAudioEnabled, setIsRemoteAudioEnabled] = useState(true);
  const [participantRoster, setParticipantRoster] = useState([]);

  const localVideoRef = useRef(null);
  const localScreenVideoRef = useRef(null);
  const remoteVideoRefs = useRef({});
  const remoteAudioRefs = useRef({});
  const remoteScreenVideoRefs = useRef({});
  const localStreamRef = useRef(null);
  const screenStreamRef = useRef(null);
  const isScreenSharingRef = useRef(false);
  const peersRef = useRef({});
  const participantsRef = useRef({});
  const screenSharingByRef = useRef({});
  const unsubscribeCallbacksRef = useRef([]);
  const peerCreationTimeoutsRef = useRef([]);
  const popoutWindowsRef = useRef({});
  const leaveNoticeTimeoutRef = useRef(null);
  const waitingPanelAlertTimeoutRef = useRef(null);
  const previousWaitingCountRef = useRef(0);
  const myParticipantRefRef = useRef(null);
  const audioAutoplayResolvedRef = useRef(false);

  const displayName = userData?.displayName || 'Používateľ';
  const uid = currentUser?.uid;

  const playWaitingJoinSound = useCallback(() => {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const audioCtx = new AudioCtx();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();

      oscillator.type = 'sine';
      oscillator.frequency.value = 880;
      gainNode.gain.value = 0.001;

      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);

      const now = audioCtx.currentTime;
      gainNode.gain.exponentialRampToValueAtTime(0.05, now + 0.03);
      gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
      oscillator.start(now);
      oscillator.stop(now + 0.22);
      oscillator.onended = () => {
        audioCtx.close().catch(() => {});
      };
    } catch (error) {
      // Browserové zvukové politiky niekedy odmietnu prehrať tón – ignorujeme.
    }
  }, []);

  const enableRemoteAudioPlayback = useCallback(() => {
    setIsRemoteAudioEnabled(true);
    Object.values(remoteAudioRefs.current).forEach((audioEl) => {
      if (!audioEl) return;
      audioEl.muted = false;
      audioEl.defaultMuted = false;
      const playPromise = audioEl.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {});
      }
    });
  }, []);

  const applyTrackPreferences = useCallback((stream, micEnabled, cameraEnabled) => {
    stream.getAudioTracks().forEach((track) => {
      track.enabled = micEnabled;
    });
    stream.getVideoTracks().forEach((track) => {
      track.enabled = cameraEnabled;
    });
  }, []);

  useEffect(() => {
    if (!uid) return undefined;

    const upsertRemoteParticipant = (remoteUid, updater) => {
      setRemoteParticipants((prev) => {
        const index = prev.findIndex((p) => p.uid === remoteUid);
        if (index === -1) {
          const base = {
            uid: remoteUid,
            displayName: 'Používateľ',
            cameraStream: new MediaStream(),
            screenStream: null
          };
          return [...prev, updater(base)];
        }
        const copy = [...prev];
        copy[index] = updater(copy[index]);
        return copy;
      });
    };

    const setupCall = async () => {
      try {
        const localStream = await getUserMediaWithFallbackOptions({
          audio: true,
          video: true,
          allowEmpty: true
        });
        applyTrackPreferences(localStream, Boolean(initialMicOn), Boolean(initialCameraOn));
        localStreamRef.current = localStream;
        attachStreamToVideo(localVideoRef.current, localStream);
        const localMicTrack = localStream.getAudioTracks()[0];
        const localCameraTrack = localStream.getVideoTracks()[0];
        setHasMicDevice(Boolean(localMicTrack));
        setHasCameraDevice(Boolean(localCameraTrack));
        setIsMicOn(localMicTrack ? localMicTrack.enabled : false);
        setIsCameraOn(localCameraTrack ? localCameraTrack.enabled : false);

        const basePath = `webrtc/${roomNumber}`;
        const participantsDbRef = ref(database, `${basePath}/participants`);
        const screenShareDbRef = ref(database, `${basePath}/screenShare`);
        const myParticipantRef = ref(database, `${basePath}/participants/${uid}`);
        myParticipantRefRef.current = myParticipantRef;

        await set(myParticipantRef, {
          uid,
          displayName,
          joinedAt: Date.now(),
          cameraOn: Boolean(initialCameraOn) && Boolean(localCameraTrack),
          micOn: Boolean(initialMicOn) && Boolean(localMicTrack)
        });
        await onDisconnect(myParticipantRef).remove();
        await onDisconnect(ref(database, `${basePath}/screenShare/${uid}`)).remove();

        const createPeer = (remoteUid, remoteName) => {
          if (peersRef.current[remoteUid]) return peersRef.current[remoteUid];

          const peerConnection = new RTCPeerConnection(RTC_PEER_CONFIG);

          // Pevné poradie transceiverov – obe strany ich vytvárajú v rovnakom poradí,
          // takže `mid` (a referencie objektov) sa zhodujú a vieme jednoznačne určiť,
          // ktorá vzdialená stopa patrí na ktoré video.
          //   mid 0 = audio
          //   mid 1 = kamera (video)
          //   mid 2 = zdieľanie obrazovky (video)
          const audioTransceiver = peerConnection.addTransceiver('audio', { direction: 'sendrecv' });
          const cameraTransceiver = peerConnection.addTransceiver('video', { direction: 'sendrecv' });
          const screenTransceiver = peerConnection.addTransceiver('video', { direction: 'sendrecv' });

          const audioSender = audioTransceiver.sender;
          const cameraSender = cameraTransceiver.sender;
          const screenSender = screenTransceiver.sender;

          // Lokálne stopy pripneme na pevne dané sendere – kamera vždy ide len na cameraSender,
          // zdieľanie obrazovky vždy len na screenSender. Žiadne duplikovanie!
          const localAudioTrack = localStreamRef.current?.getAudioTracks?.()[0] || null;
          const localCamTrack = localStreamRef.current?.getVideoTracks?.()[0] || null;
          const activeScreenTrack = screenStreamRef.current?.getVideoTracks?.()[0] || null;

          if (localAudioTrack) {
            audioSender.replaceTrack(localAudioTrack).catch((error) => {
              console.error('Chyba pri pripnutí audio tracku:', error);
            });
          }
          if (localCamTrack) {
            cameraSender.replaceTrack(localCamTrack).catch((error) => {
              console.error('Chyba pri pripnutí kamerového tracku:', error);
            });
          }
          if (activeScreenTrack) {
            screenSender.replaceTrack(activeScreenTrack).catch((error) => {
              console.error('Chyba pri pripnutí screen tracku:', error);
            });
          }

          let cleanupOfferListener = null;
          let cleanupAnswerListener = null;
          const pendingIceCandidates = [];

          const flushPendingIceCandidates = async () => {
            if (!peerConnection.remoteDescription) return;
            while (pendingIceCandidates.length > 0) {
              if (peerConnection.signalingState === 'closed' || peerConnection.connectionState === 'closed') {
                pendingIceCandidates.length = 0;
                return;
              }
              const candidateData = pendingIceCandidates.shift();
              try {
                await peerConnection.addIceCandidate(new RTCIceCandidate(candidateData));
              } catch (error) {
                if (peerConnection.signalingState !== 'closed' && peerConnection.connectionState !== 'closed') {
                  console.error('Chyba pri aplikovaní čakajúceho ICE kandidáta:', error);
                }
              }
            }
          };

          peerConnection.addEventListener('connectionstatechange', () => {
            const s = peerConnection.connectionState;
            if (s === 'failed' || s === 'disconnected') {
              try {
                peerConnection.restartIce();
              } catch (e) {
                /* ignore */
              }
            }
          });

          peerConnection.ontrack = (event) => {
            const track = event.track;
            const tcv = event.transceiver;

            const isAudioTrack = track.kind === 'audio';
            const isScreenTrack =
              track.kind === 'video' &&
              (tcv === screenTransceiver || (tcv?.mid && screenTransceiver?.mid && tcv.mid === screenTransceiver.mid));
            const isCameraTrack =
              track.kind === 'video' &&
              !isScreenTrack &&
              (tcv === cameraTransceiver || (tcv?.mid && cameraTransceiver?.mid && tcv.mid === cameraTransceiver.mid));

            upsertRemoteParticipant(remoteUid, (participant) => {
              const next = {
                ...participant,
                displayName: remoteName || participant.displayName || 'Používateľ'
              };

              if (isAudioTrack) {
                const otherTracks = next.cameraStream
                  .getTracks()
                  .filter((t) => t.kind !== 'audio');
                next.cameraStream = new MediaStream([...otherTracks, track]);
              } else if (isScreenTrack) {
                next.screenStream = new MediaStream([track]);
              } else if (isCameraTrack) {
                const audioTracks = next.cameraStream.getAudioTracks();
                next.cameraStream = new MediaStream([...audioTracks, track]);
              } else {
                // Veľmi výnimočný prípad – ak by sa kvôli zlyhaniu negociácie nepodarilo
                // určiť pôvod stopy, predvolene ju umiestnime ako kameru, aby sa
                // nezamenila s reálne zdieľanou obrazovkou.
                const audioTracks = next.cameraStream.getAudioTracks();
                next.cameraStream = new MediaStream([...audioTracks, track]);
              }

              return next;
            });

            track.addEventListener('ended', () => {
              upsertRemoteParticipant(remoteUid, (participant) => {
                const next = { ...participant };
                if (next.screenStream && next.screenStream.getTracks().some((t) => t.id === track.id)) {
                  const remaining = next.screenStream.getTracks().filter((t) => t.id !== track.id);
                  next.screenStream = remaining.length ? new MediaStream(remaining) : null;
                }
                if (next.cameraStream && next.cameraStream.getTracks().some((t) => t.id === track.id)) {
                  const remaining = next.cameraStream.getTracks().filter((t) => t.id !== track.id);
                  next.cameraStream = new MediaStream(remaining);
                }
                return next;
              });
            });
          };

          peerConnection.onicecandidate = async (event) => {
            if (event.candidate) {
              try {
                await push(
                  ref(database, `${basePath}/candidates/${uid}/${remoteUid}`),
                  event.candidate.toJSON()
                );
              } catch (error) {
                console.error('Chyba pri zápise ICE kandidáta:', error);
              }
            }
          };

          const cleanupRemoteCandidates = onChildAdded(
            ref(database, `${basePath}/candidates/${remoteUid}/${uid}`),
            async (snapshot) => {
              const candidateData = snapshot.val();
              if (!candidateData) return;
              if (peerConnection.signalingState === 'closed' || peerConnection.connectionState === 'closed') {
                return;
              }
              if (!peerConnection.remoteDescription) {
                pendingIceCandidates.push(candidateData);
                return;
              }
              try {
                await peerConnection.addIceCandidate(new RTCIceCandidate(candidateData));
              } catch (error) {
                if (peerConnection.signalingState !== 'closed' && peerConnection.connectionState !== 'closed') {
                  console.error('Chyba pri ICE kandidátovi:', error);
                }
              }
            }
          );

          const publishOffer = async () => {
            if (peerConnection.signalingState !== 'stable') return false;
            const offer = await peerConnection.createOffer();
            await peerConnection.setLocalDescription(offer);
            await set(ref(database, `${basePath}/offers/${uid}/${remoteUid}`), {
              type: offer.type,
              sdp: offer.sdp
            });
            return true;
          };

          cleanupAnswerListener = onValue(
            ref(database, `${basePath}/answers/${remoteUid}/${uid}`),
            async (snapshot) => {
              const answer = snapshot.val();
              if (!answer) return;
              if (peerConnection.signalingState !== 'have-local-offer') return;
              try {
                await peerConnection.setRemoteDescription(new RTCSessionDescription(answer));
                await flushPendingIceCandidates();
              } catch (error) {
                console.error('Chyba pri remote answer:', error);
              }
            }
          );

          cleanupOfferListener = onValue(
            ref(database, `${basePath}/offers/${remoteUid}/${uid}`),
            async (snapshot) => {
              const offer = snapshot.val();
              if (!offer) return;
              if (peerConnection.signalingState !== 'stable') return;
              try {
                await peerConnection.setRemoteDescription(new RTCSessionDescription(offer));
                await flushPendingIceCandidates();
                const answer = await peerConnection.createAnswer();
                await peerConnection.setLocalDescription(answer);
                await set(ref(database, `${basePath}/answers/${uid}/${remoteUid}`), {
                  type: answer.type,
                  sdp: answer.sdp
                });
              } catch (error) {
                console.error('Chyba pri remote offer:', error);
              }
            }
          );

          // Deterministicky určíme, kto je offerer (lexikograficky menší uid),
          // aby sa neoffrovalo z oboch strán súčasne.
          const isOfferer = uid < remoteUid;
          if (isOfferer) {
            publishOffer().catch((error) => {
              console.error('Chyba pri vytváraní offer:', error);
            });
          }

          const destroyPeer = async () => {
            if (cleanupOfferListener) cleanupOfferListener();
            if (cleanupAnswerListener) cleanupAnswerListener();
            cleanupRemoteCandidates();
            try {
              peerConnection.close();
            } catch (e) {
              /* ignore */
            }

            setRemoteParticipants((prev) => prev.filter((p) => p.uid !== remoteUid));
            delete peersRef.current[remoteUid];

            try {
              await remove(ref(database, `${basePath}/offers/${uid}/${remoteUid}`));
              await remove(ref(database, `${basePath}/offers/${remoteUid}/${uid}`));
              await remove(ref(database, `${basePath}/answers/${uid}/${remoteUid}`));
              await remove(ref(database, `${basePath}/answers/${remoteUid}/${uid}`));
              await remove(ref(database, `${basePath}/candidates/${uid}/${remoteUid}`));
              await remove(ref(database, `${basePath}/candidates/${remoteUid}/${uid}`));
            } catch (error) {
              console.error('Chyba pri čistení peer signalizácie:', error);
            }
          };

          const peerData = {
            peerConnection,
            destroyPeer,
            audioSender,
            cameraSender,
            screenSender,
            publishOffer
          };
          peersRef.current[remoteUid] = peerData;
          return peerData;
        };

        const participantsUnsubscribe = onValue(participantsDbRef, (snapshot) => {
          const data = snapshot.val() || {};
          participantsRef.current = data;
          setParticipantRoster(
            Object.entries(data).map(([id, v]) => ({
              uid: id,
              displayName: v?.displayName || 'Používateľ'
            }))
          );
          const participantIds = Object.keys(data).filter((id) => id !== uid);

          // Tvrdá synchronizácia – odíduvšieho účastníka odstránime, aby sa nezasekla čierna dlaždica.
          setRemoteParticipants((prev) => {
            const departed = prev.filter((participant) => !participantIds.includes(participant.uid));
            if (departed.length > 0) {
              const noticeName = departed[0].displayName || 'Používateľ';
              setLeaveNotice(`${noticeName} opustil miestnosť`);
              if (leaveNoticeTimeoutRef.current) {
                clearTimeout(leaveNoticeTimeoutRef.current);
              }
              leaveNoticeTimeoutRef.current = window.setTimeout(() => {
                setLeaveNotice('');
              }, 3500);
            }
            return prev.filter((participant) => participantIds.includes(participant.uid));
          });

          participantIds.forEach((remoteUid, index) => {
            const remoteName = data[remoteUid]?.displayName;
            const remoteCameraOn = data[remoteUid]?.cameraOn !== false;
            setRemoteParticipants((prev) => {
              if (prev.some((participant) => participant.uid === remoteUid)) {
                return prev.map((participant) =>
                  participant.uid === remoteUid
                    ? {
                        ...participant,
                        displayName: remoteName || participant.displayName || 'Používateľ',
                        cameraOn: remoteCameraOn
                      }
                    : participant
                );
              }
              return [
                ...prev,
                {
                  uid: remoteUid,
                  displayName: remoteName || 'Používateľ',
                  cameraOn: remoteCameraOn,
                  cameraStream: new MediaStream(),
                  screenStream: null
                }
              ];
            });
            if (!peersRef.current[remoteUid]) {
              const delayMs = index * 120;
              const tid = window.setTimeout(() => {
                if (!participantsRef.current[remoteUid]) return;
                if (peersRef.current[remoteUid]) return;
                createPeer(remoteUid, participantsRef.current[remoteUid]?.displayName || remoteName);
              }, delayMs);
              peerCreationTimeoutsRef.current.push(tid);
            }
          });

          Object.keys(peersRef.current).forEach((remoteUid) => {
            if (!participantIds.includes(remoteUid)) {
              const peer = peersRef.current[remoteUid];
              if (peer) peer.destroyPeer();
            }
          });

          setScreenSharingBy((prev) => {
            const next = {};
            Object.keys(prev).forEach((participantId) => {
              if (participantIds.includes(participantId)) {
                next[participantId] = prev[participantId];
              }
            });
            screenSharingByRef.current = next;
            return next;
          });

          const total = participantIds.length + 1;
          if (total <= 1) {
            setStatus('Čakám na ďalších účastníkov...');
          } else {
            setStatus(`Pripojení účastníci: ${total}`);
          }
        });
        unsubscribeCallbacksRef.current.push(participantsUnsubscribe);

        const screenShareUnsubscribe = onValue(screenShareDbRef, (snapshot) => {
          const data = snapshot.val() || {};
          const normalized = {};
          Object.keys(data).forEach((participantId) => {
            normalized[participantId] = Boolean(data[participantId]?.isSharing);
          });
          screenSharingByRef.current = normalized;
          setScreenSharingBy(normalized);
          setRemoteParticipants((prev) =>
            prev.map((participant) => {
              if (!normalized[participant.uid]) {
                // Niekto skončil zdieľanie – jeho screenStream zahodíme,
                // aby UI okamžite reflektoval stav.
                return {
                  ...participant,
                  screenStream: null
                };
              }
              return participant;
            })
          );
        });
        unsubscribeCallbacksRef.current.push(screenShareUnsubscribe);
      } catch (error) {
        console.error('Chyba pri spúšťaní hovoru:', error);
        setStatus('Nepodarilo sa spustiť spojenie. Skús obnoviť stránku.');
      }
    };

    setupCall();

    return () => {
      peerCreationTimeoutsRef.current.forEach((tid) => clearTimeout(tid));
      peerCreationTimeoutsRef.current = [];
      if (leaveNoticeTimeoutRef.current) {
        clearTimeout(leaveNoticeTimeoutRef.current);
        leaveNoticeTimeoutRef.current = null;
      }

      unsubscribeCallbacksRef.current.forEach((unsubscribe) => unsubscribe());
      unsubscribeCallbacksRef.current = [];

      Object.keys(peersRef.current).forEach((remoteUid) => {
        const peer = peersRef.current[remoteUid];
        if (peer) {
          try {
            peer.peerConnection.close();
          } catch (e) {
            /* ignore */
          }
        }
      });
      peersRef.current = {};

      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((track) => track.stop());
        screenStreamRef.current = null;
      }

      if (localStreamRef.current) {
        localStreamRef.current.getTracks().forEach((track) => track.stop());
        localStreamRef.current = null;
      }

      setRemoteParticipants([]);
      setParticipantRoster([]);
      setScreenSharingBy({});
      remoteAudioRefs.current = {};
      isScreenSharingRef.current = false;
      setIsScreenSharing(false);
      myParticipantRefRef.current = null;
      remove(ref(database, `webrtc/${roomNumber}/participants/${uid}`));
      remove(ref(database, `webrtc/${roomNumber}/screenShare/${uid}`));
    };
  }, [roomNumber, uid, displayName, applyTrackPreferences, initialMicOn, initialCameraOn]);

  // Pokus o automatické zapnutie zvuku pri akejkoľvek interakcii s dokumentom.
  // Browsery povolia prehrávanie zvuku až po user gesture, takže prvý klik kamkoľvek na stránke
  // spustí play() pre všetky pripojené audio elementy a používateľ nepríde o hlas účastníkov.
  useEffect(() => {
    if (audioAutoplayResolvedRef.current) return undefined;
    const handler = () => {
      if (audioAutoplayResolvedRef.current) return;
      audioAutoplayResolvedRef.current = true;
      enableRemoteAudioPlayback();
    };
    window.addEventListener('pointerdown', handler, { once: true });
    window.addEventListener('keydown', handler, { once: true });
    window.addEventListener('touchstart', handler, { once: true, passive: true });
    return () => {
      window.removeEventListener('pointerdown', handler);
      window.removeEventListener('keydown', handler);
      window.removeEventListener('touchstart', handler);
    };
  }, [enableRemoteAudioPlayback]);

  // Pri pribudnutí účastníka skúsime audio elementy hneď spustiť (ak už máme povolené prehrávanie).
  useEffect(() => {
    if (!isRemoteAudioEnabled) return;
    Object.values(remoteAudioRefs.current).forEach((el) => {
      if (!el) return;
      el.muted = false;
      const playPromise = el.play?.();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          // Autoplay zatiaľ blokovaný – ostáva tlačidlo na manuálne zapnutie.
          setIsRemoteAudioEnabled(false);
        });
      }
    });
  }, [remoteParticipants, isRemoteAudioEnabled]);

  const executeLeave = async (endMeetingForAll = false) => {
    if (isLeaving) return;
    setIsLeaving(true);

    peerCreationTimeoutsRef.current.forEach((tid) => clearTimeout(tid));
    peerCreationTimeoutsRef.current = [];
    if (leaveNoticeTimeoutRef.current) {
      clearTimeout(leaveNoticeTimeoutRef.current);
      leaveNoticeTimeoutRef.current = null;
    }

    unsubscribeCallbacksRef.current.forEach((unsubscribe) => unsubscribe());
    unsubscribeCallbacksRef.current = [];

    const peerIds = Object.keys(peersRef.current);
    await Promise.all(
      peerIds.map(async (remoteUid) => {
        const peer = peersRef.current[remoteUid];
        if (peer) {
          try {
            peer.peerConnection.close();
          } catch (e) {
            /* ignore */
          }
        }
        try {
          await remove(ref(database, `webrtc/${roomNumber}/offers/${uid}/${remoteUid}`));
          await remove(ref(database, `webrtc/${roomNumber}/offers/${remoteUid}/${uid}`));
          await remove(ref(database, `webrtc/${roomNumber}/answers/${uid}/${remoteUid}`));
          await remove(ref(database, `webrtc/${roomNumber}/answers/${remoteUid}/${uid}`));
          await remove(ref(database, `webrtc/${roomNumber}/candidates/${uid}/${remoteUid}`));
          await remove(ref(database, `webrtc/${roomNumber}/candidates/${remoteUid}/${uid}`));
        } catch (error) {
          console.error('Chyba pri čistení signalizácie:', error);
        }
      })
    );
    peersRef.current = {};

    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach((track) => track.stop());
      screenStreamRef.current = null;
    }

    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((track) => track.stop());
      localStreamRef.current = null;
    }

    setRemoteParticipants([]);
    setParticipantRoster([]);
    setScreenSharingBy({});
    remoteAudioRefs.current = {};
    myParticipantRefRef.current = null;

    try {
      await remove(ref(database, `webrtc/${roomNumber}/participants/${uid}`));
      await remove(ref(database, `webrtc/${roomNumber}/screenShare/${uid}`));
      if (isHost && endMeetingForAll) {
        await remove(ref(database, `webrtc/${roomNumber}`));
      }
    } catch (error) {
      console.error('Chyba pri čistení WebRTC dát:', error);
    }
    onLeave({ endMeetingForAll });
  };

  const handleLeave = async () => {
    if (isHost) {
      setShowHostLeaveDialog(true);
      return;
    }
    await executeLeave(false);
  };

  const refreshLocalMedia = useCallback(async () => {
    try {
      setStatus('Obnovujem kameru a mikrofón...');
      const oldStream = localStreamRef.current;
      if (oldStream) {
        oldStream.getTracks().forEach((t) => t.stop());
      }

      const newStream = await getUserMediaWithFallbackOptions({
        audio: true,
        video: true,
        allowEmpty: true
      });
      localStreamRef.current = newStream;
      attachStreamToVideo(localVideoRef.current, newStream);

      const mic = newStream.getAudioTracks()[0];
      const cam = newStream.getVideoTracks()[0];
      setHasMicDevice(Boolean(mic));
      setHasCameraDevice(Boolean(cam));
      setIsMicOn(mic ? mic.enabled : false);
      setIsCameraOn(cam ? cam.enabled : false);

      const peerList = Object.values(peersRef.current);
      for (const peer of peerList) {
        const { audioSender, cameraSender } = peer;
        if (audioSender) {
          await audioSender.replaceTrack(mic || null);
        }
        if (cameraSender) {
          await cameraSender.replaceTrack(cam || null);
        }
      }

      const total = Object.keys(peersRef.current).length + 1;
      setStatus(`Pripojení účastníci: ${total}`);
    } catch (error) {
      console.error('Obnova médií zlyhala:', error);
      setStatus('Nepodarilo sa obnoviť kameru/mikrofón');
    }
  }, []);

  const handleToggleMic = async () => {
    const stream = localStreamRef.current;
    if (!stream) {
      setHasMicDevice(false);
      setIsMicOn(false);
      setStatus('Mikrofón nie je na tomto zariadení dostupný.');
      return;
    }

    const audioTracks = stream.getAudioTracks();
    const audioTrack = audioTracks[0];
    if (!audioTrack || audioTrack.readyState === 'ended') {
      setHasMicDevice(false);
      setIsMicOn(false);
      setStatus('Mikrofón nie je na tomto zariadení dostupný.');
      return;
    }

    const nextMicState = !isMicOn;
    audioTracks.forEach((track) => {
      track.enabled = nextMicState;
    });
    await Promise.all(
      Object.values(peersRef.current).map(async (peer) => {
        if (!peer.audioSender) return;
        try {
          // Aj pri stlmení posielame stopu ďalej (track.enabled=false zabezpečí ticho).
          // Replaceovanie na null by spôsobilo, že po opätovnom zapnutí mikrofónu
          // by druhá strana neprijímala zvuk, kým by neprebehla nová negociácia.
          if (peer.audioSender.track?.id !== audioTrack.id) {
            await peer.audioSender.replaceTrack(audioTrack);
          }
        } catch (error) {
          console.error('Chyba pri prepnutí mikrofónu na peer spojení:', error);
        }
      })
    );
    setIsMicOn(nextMicState);
    if (myParticipantRefRef.current) {
      update(myParticipantRefRef.current, { micOn: nextMicState }).catch((error) => {
        console.error('Chyba pri zápise stavu mikrofónu:', error);
      });
    }
  };

  const handleToggleCamera = async () => {
    const stream = localStreamRef.current;
    if (!stream) {
      setHasCameraDevice(false);
      setIsCameraOn(false);
      setStatus('Kamera nie je na tomto zariadení dostupná.');
      return;
    }

    const videoTracks = stream.getVideoTracks();
    const videoTrack = videoTracks[0];
    if (!videoTrack || videoTrack.readyState === 'ended') {
      setHasCameraDevice(false);
      setIsCameraOn(false);
      setStatus('Kamera nie je na tomto zariadení dostupná.');
      return;
    }

    const nextCameraState = !isCameraOn;
    videoTracks.forEach((track) => {
      track.enabled = nextCameraState;
    });
    // Camera sender vždy drží kamerový track (aj keď je momentálne disabled).
    // Vďaka tomu sa nemusí preanalyzovať spojenie pri každom zapnutí kamery,
    // a hlavne to nezasahuje do nezávislého screen sender-a pri zdieľaní obrazovky.
    await Promise.all(
      Object.values(peersRef.current).map(async (peer) => {
        if (!peer.cameraSender) return;
        try {
          if (peer.cameraSender.track?.id !== videoTrack.id) {
            await peer.cameraSender.replaceTrack(videoTrack);
          }
        } catch (error) {
          console.error('Chyba pri opätovnom pripnutí kamery na peer spojení:', error);
        }
      })
    );
    setIsCameraOn(nextCameraState);
    if (myParticipantRefRef.current) {
      update(myParticipantRefRef.current, { cameraOn: nextCameraState }).catch((error) => {
        console.error('Chyba pri zápise stavu kamery:', error);
      });
    }
  };

  const stopScreenShare = async () => {
    await Promise.all(
      Object.values(peersRef.current).map(async (peer) => {
        if (!peer.screenSender) return;
        try {
          await peer.screenSender.replaceTrack(null);
        } catch (error) {
          console.error('Chyba pri uvoľnení screen senderu:', error);
        }
      })
    );

    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach((track) => track.stop());
      screenStreamRef.current = null;
    }

    isScreenSharingRef.current = false;
    setIsScreenSharing(false);
    if (uid) {
      try {
        await remove(ref(database, `webrtc/${roomNumber}/screenShare/${uid}`));
      } catch (error) {
        console.error('Chyba pri zápise stavu zdieľania:', error);
      }
    }
  };

  const handleToggleScreenShare = async () => {
    try {
      if (isScreenSharingRef.current) {
        await stopScreenShare();
        return;
      }

      if (!navigator.mediaDevices?.getDisplayMedia) {
        setStatus('Tento prehliadač nepodporuje zdieľanie obrazovky.');
        return;
      }

      const displayStream = await navigator.mediaDevices.getDisplayMedia({
        video: { frameRate: { ideal: 15, max: 24 } },
        audio: false
      });
      const screenTrack = displayStream.getVideoTracks()[0];
      if (!screenTrack) return;
      screenTrack.contentHint = 'detail';

      screenTrack.onended = () => {
        if (isScreenSharingRef.current) {
          stopScreenShare().catch((error) => {
            console.error('Chyba pri ukončení zdieľania obrazovky:', error);
          });
        }
      };

      screenStreamRef.current = displayStream;
      isScreenSharingRef.current = true;
      setIsScreenSharing(true);

      if (uid) {
        try {
          await set(ref(database, `webrtc/${roomNumber}/screenShare/${uid}`), {
            isSharing: true,
            updatedAt: Date.now()
          });
        } catch (error) {
          console.error('Chyba pri zápise stavu zdieľania:', error);
        }
      }

      // Screen track ide IBA na dedikovaný screenSender. Žiadne posielanie
      // na cameraSender – to predtým spôsobovalo, že druhá strana videla
      // zdieľanú obrazovku v dvoch dlaždiciach a kamera sa stratila.
      await Promise.all(
        Object.values(peersRef.current).map(async (peer) => {
          if (!peer.screenSender) return;
          try {
            await peer.screenSender.replaceTrack(screenTrack);
          } catch (error) {
            console.error('Chyba pri pripnutí screen tracku na peer:', error);
          }
        })
      );
    } catch (error) {
      if (error?.name !== 'NotAllowedError' && error?.name !== 'AbortError') {
        console.error('Chyba pri zdieľaní obrazovky:', error);
        setStatus('Zdieľanie obrazovky zlyhalo. Skús to znova.');
      }
    }
  };

  // Auto-výber pripnutej dlaždice. Ak používateľ niečo aktívne pripol a tile
  // ešte existuje, ostane pripnuté – inak prepneme na rozumný default.
  useEffect(() => {
    const availableFocusIds = ['local'];
    if (isScreenSharing && screenStreamRef.current) {
      availableFocusIds.push('local-screen');
    }
    remoteParticipants.forEach((participant) => {
      availableFocusIds.push(participant.uid);
      if (screenSharingBy[participant.uid] && streamHasLiveVideo(participant.screenStream)) {
        availableFocusIds.push(`screen-${participant.uid}`);
      }
    });

    if (focusedParticipantId && availableFocusIds.includes(focusedParticipantId)) {
      return;
    }

    const sharedRemote = remoteParticipants.find(
      (participant) =>
        screenSharingBy[participant.uid] && streamHasLiveVideo(participant.screenStream)
    );
    if (sharedRemote) {
      setFocusedParticipantId(`screen-${sharedRemote.uid}`);
      return;
    }
    if (isScreenSharing && screenStreamRef.current) {
      setFocusedParticipantId('local-screen');
      return;
    }
    if (remoteParticipants.length > 0) {
      setFocusedParticipantId(remoteParticipants[0].uid);
      return;
    }
    setFocusedParticipantId('local');
  }, [remoteParticipants, screenSharingBy, isScreenSharing, focusedParticipantId]);

  useEffect(() => {
    return () => {
      Object.values(popoutWindowsRef.current).forEach((w) => {
        if (w && !w.closed) {
          w.close();
        }
      });
      popoutWindowsRef.current = {};
      if (waitingPanelAlertTimeoutRef.current) {
        clearTimeout(waitingPanelAlertTimeoutRef.current);
        waitingPanelAlertTimeoutRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!isHost) {
      previousWaitingCountRef.current = waitingUsers.length;
      setIsWaitingPanelAlert(false);
      if (waitingPanelAlertTimeoutRef.current) {
        clearTimeout(waitingPanelAlertTimeoutRef.current);
        waitingPanelAlertTimeoutRef.current = null;
      }
      return;
    }

    const previousCount = previousWaitingCountRef.current;
    const currentCount = waitingUsers.length;
    const hasNewJoinRequest = currentCount > previousCount && currentCount > 0;

    if (hasNewJoinRequest) {
      setIsWaitingPanelAlert(true);
      playWaitingJoinSound();
      if (waitingPanelAlertTimeoutRef.current) {
        clearTimeout(waitingPanelAlertTimeoutRef.current);
      }
      waitingPanelAlertTimeoutRef.current = window.setTimeout(() => {
        setIsWaitingPanelAlert(false);
      }, 3000);
    }

    previousWaitingCountRef.current = currentCount;
  }, [isHost, waitingUsers, playWaitingJoinSound]);

  const getPlayableStream = (stream) => {
    if (!stream) return null;
    const liveVideoTracks = stream
      .getVideoTracks()
      .filter((track) => track.readyState === 'live');
    if (liveVideoTracks.length === 0) return null;
    return stream;
  };

  const openStreamInPopup = (key, title, stream) => {
    if (!stream) {
      alert('Vybraný stream momentálne nie je dostupný.');
      return;
    }

    const existing = popoutWindowsRef.current[key];
    if (existing && !existing.closed) {
      existing.focus();
      const existingVideo = existing.document.getElementById('popup-video');
      if (existingVideo) {
        existingVideo.muted = true;
        existingVideo.defaultMuted = true;
        attachStreamToVideo(existingVideo, stream);
        existingVideo.onloadedmetadata = () => {
          existingVideo.play().catch(() => {});
        };
        existingVideo.oncanplay = () => {
          existingVideo.play().catch(() => {});
        };
      }
      return;
    }

    const popup = window.open('', `_blank`, 'width=1200,height=800');
    if (!popup) {
      alert('Prehliadač zablokoval popup okno. Povoľ pop-up okná pre tento web.');
      return;
    }

    popup.document.write(`
      <!doctype html>
      <html>
        <head>
          <title>${title}</title>
          <style>
            body { margin:0; background:#000; color:#fff; font-family:Arial,sans-serif; }
            .header { padding:10px 14px; background:#111; border-bottom:1px solid #333; }
            video { width:100vw; height:calc(100vh - 44px); object-fit:contain; background:#000; }
          </style>
        </head>
        <body>
          <div class="header">${title}</div>
          <video id="popup-video" autoplay playsinline muted></video>
        </body>
      </html>
    `);
    popup.document.close();

    const popupVideo = popup.document.getElementById('popup-video');
    if (popupVideo) {
      popupVideo.muted = true;
      popupVideo.defaultMuted = true;
      attachStreamToVideo(popupVideo, stream);
      popupVideo.onloadedmetadata = () => {
        popupVideo.play().catch(() => {});
      };
      popupVideo.oncanplay = () => {
        popupVideo.play().catch(() => {});
      };
    }

    popoutWindowsRef.current[key] = popup;
  };

  const handleFullscreenFocused = async () => {
    const requestVideoFullscreen = async (videoEl) => {
      if (!videoEl) return false;
      try {
        if (videoEl.requestFullscreen) {
          await videoEl.requestFullscreen();
          return true;
        }
        if (videoEl.webkitRequestFullscreen) {
          videoEl.webkitRequestFullscreen();
          return true;
        }
        if (videoEl.webkitEnterFullscreen) {
          videoEl.webkitEnterFullscreen();
          return true;
        }
      } catch (error) {
        console.error('Fullscreen zlyhal:', error);
      }
      return false;
    };

    let selectedVideoEl = null;
    if (focusedParticipantId === 'local') {
      selectedVideoEl = localVideoRef.current;
    } else if (focusedParticipantId === 'local-screen') {
      selectedVideoEl = localScreenVideoRef.current;
    } else if (focusedParticipantId?.startsWith('screen-')) {
      const uidFromFocus = focusedParticipantId.replace('screen-', '');
      selectedVideoEl = remoteScreenVideoRefs.current[uidFromFocus] || null;
    } else {
      selectedVideoEl = remoteVideoRefs.current[focusedParticipantId] || null;
    }

    const enteredFullscreen = await requestVideoFullscreen(selectedVideoEl);
    if (!enteredFullscreen) {
      setStatus('Fullscreen nie je na tomto zariadení podporovaný. Vybrané video ostáva pripnuté vo veľkom.');
    }
  };

  const handleOpenSplitLayout = () => {
    if (!isPinnedView) {
      setStatus('Nemáš pripnuté žiadne video na rozdelenie. Najprv klikni na dlaždicu, ktorú chceš zobraziť v samostatnom okne.');
      return;
    }

    let popupKey = null;
    let popupTitle = '';
    let streamToOpen = null;

    if (focusedParticipantId === 'local') {
      popupKey = 'local';
      popupTitle = `Kamera - ${displayName}`;
      streamToOpen = localStreamRef.current;
    } else if (focusedParticipantId === 'local-screen') {
      popupKey = 'local-screen';
      popupTitle = `Zdieľaná obrazovka - ${displayName}`;
      streamToOpen = screenStreamRef.current;
    } else if (focusedParticipantId?.startsWith('screen-')) {
      const remoteUid = focusedParticipantId.replace('screen-', '');
      const participant = remoteParticipants.find((p) => p.uid === remoteUid);
      popupKey = `screen-${remoteUid}`;
      popupTitle = `${participant?.displayName || 'Používateľ'} - zdieľaná obrazovka`;
      streamToOpen = participant?.screenStream || null;
    } else {
      const participant = remoteParticipants.find((p) => p.uid === focusedParticipantId);
      popupKey = `participant-${focusedParticipantId || 'unknown'}`;
      popupTitle = `Účastník - ${participant?.displayName || 'Používateľ'}`;
      streamToOpen = participant?.cameraStream || null;
    }

    const playableStream = getPlayableStream(streamToOpen);
    if (!playableStream) {
      setStatus('Vybrané video momentálne nie je dostupné. Skús pripnúť inú dlaždicu alebo počkaj na obnovenie streamu.');
      return;
    }

    openStreamInPopup(popupKey, popupTitle, playableStream);
  };

  const activeRemoteParticipantIds = new Set(
    participantRoster.map((participant) => participant.uid).filter((participantId) => participantId !== uid)
  );
  const visibleRemoteParticipants = remoteParticipants.filter((participant) =>
    activeRemoteParticipantIds.has(participant.uid)
  );

  return (
    <div className="meeting-room">
      <div className="meeting-header">
        <h2>📹 Miestnosť {roomNumber}</h2>
        <div className="header-info">
          <span>👤 {displayName}</span>
          <button className="btn-leave" onClick={handleLeave}>
            🚪 Opustiť
          </button>
        </div>
      </div>

      <div className="meeting-content">
        <p className="meeting-instruction">{status}</p>
        <>
          {leaveNotice ? <p className="meeting-toast">{leaveNotice}</p> : null}
          {isHost && waitingUsers.length > 0 && (
            <div
              className={`meeting-admin-panel meeting-admin-panel-sticky ${isWaitingPanelAlert ? 'meeting-admin-panel-alert' : ''}`}
            >
              <h3>Čakajúci používatelia ({waitingUsers.length})</h3>
              <div className="meeting-waiting-list">
                {waitingUsers.map((user) => (
                  <div key={user.id} className="meeting-waiting-user">
                    <span>👤 {user.displayName}</span>
                    <div className="meeting-user-actions">
                      <button
                        className="btn-admit"
                        onClick={() => onAdmitUser && onAdmitUser(user.id)}
                      >
                        Prijať
                      </button>
                      <button
                        className="btn-reject"
                        onClick={() => onRejectUser && onRejectUser(user.id)}
                      >
                        Zamietnuť
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="focus-controls">
            <button className="control-btn on" onClick={handleFullscreenFocused}>
              ⛶ Zväčšiť vybrané video
            </button>
            <button className={`control-btn ${isPinnedView ? 'off' : 'on'}`} onClick={() => setIsPinnedView(false)}>
              📌 Zrušiť pripnutie (Unpin)
            </button>
            <button className="control-btn on" onClick={handleOpenSplitLayout}>
              🖥️ Rozdeliť na viac monitorov
            </button>
          </div>

          <div className={`video-grid ${isPinnedView ? 'pinned-mode' : ''}`}>
            <div
              className={`video-card ${focusedParticipantId === 'local' ? 'focused' : ''} ${isCameraOn ? '' : 'no-video'}`}
              onClick={() => {
                setFocusedParticipantId('local');
                setIsPinnedView(true);
              }}
            >
              <p>
                Ty ({displayName}) {isScreenSharing ? ' - zdieľa obrazovku' : ''}
              </p>
              <video ref={localVideoRef} autoPlay playsInline muted className="local-self-video" />
              {!isCameraOn && <div className="video-avatar-placeholder">👤</div>}
            </div>

            {isScreenSharing && screenStreamRef.current && (
              <div
                className={`video-card ${focusedParticipantId === 'local-screen' ? 'focused' : ''}`}
                onClick={() => {
                  setFocusedParticipantId('local-screen');
                  setIsPinnedView(true);
                }}
              >
                <p>Tvoje zdieľanie obrazovky</p>
                <video
                  autoPlay
                  playsInline
                  muted
                  ref={(el) => {
                    localScreenVideoRef.current = el;
                    if (el && screenStreamRef.current) {
                      attachStreamToVideo(el, screenStreamRef.current);
                    }
                  }}
                />
              </div>
            )}

            {visibleRemoteParticipants.map((participant) => {
              const remoteScreenStream = streamHasLiveVideo(participant.screenStream)
                ? participant.screenStream
                : null;
              const remoteHasVideo =
                participant.cameraOn !== false && streamHasLiveVideo(participant.cameraStream);
              const isSharingScreen = Boolean(screenSharingBy[participant.uid]);
              return (
                <React.Fragment key={participant.uid}>
                  <div
                    className={`video-card ${focusedParticipantId === participant.uid ? 'focused' : ''} ${remoteHasVideo ? '' : 'no-video'}`}
                    onClick={() => {
                      setFocusedParticipantId(participant.uid);
                      setIsPinnedView(true);
                    }}
                  >
                    <p>{participant.displayName || 'Používateľ'}</p>
                    <video
                      autoPlay
                      playsInline
                      muted
                      ref={(el) => {
                        if (el && participant.cameraStream) {
                          attachStreamToVideo(el, participant.cameraStream);
                          remoteVideoRefs.current[participant.uid] = el;
                        }
                        if (!el) {
                          delete remoteVideoRefs.current[participant.uid];
                        }
                      }}
                    />
                    <audio
                      autoPlay
                      playsInline
                      ref={(el) => {
                        if (el && participant.cameraStream) {
                          el.muted = !isRemoteAudioEnabled;
                          attachStreamToVideo(el, participant.cameraStream);
                          remoteAudioRefs.current[participant.uid] = el;
                        }
                        if (!el) {
                          delete remoteAudioRefs.current[participant.uid];
                        }
                      }}
                    />
                    {!remoteHasVideo && <div className="video-avatar-placeholder">👤</div>}
                  </div>

                  {isSharingScreen && (
                    <div
                      className={`video-card ${focusedParticipantId === `screen-${participant.uid}` ? 'focused' : ''}`}
                      onClick={() => {
                        setFocusedParticipantId(`screen-${participant.uid}`);
                        setIsPinnedView(true);
                      }}
                    >
                      <p>{participant.displayName || 'Používateľ'} - zdieľa obrazovku</p>
                      <video
                        autoPlay
                        playsInline
                        muted
                        ref={(el) => {
                          if (el && remoteScreenStream) {
                            attachStreamToVideo(el, remoteScreenStream);
                            remoteScreenVideoRefs.current[participant.uid] = el;
                          }
                          if (!el) {
                            delete remoteScreenVideoRefs.current[participant.uid];
                          }
                        }}
                      />
                      {!remoteScreenStream && <div className="video-avatar-placeholder">🖥️</div>}
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>

          <p className="meeting-note">Klikni na video: pripne sa vo veľkom. Potom môžeš zapnúť fullscreen.</p>

          <PresentationPanel
            roomNumber={roomNumber}
            uid={uid}
            displayName={displayName}
            isHost={isHost}
            participantRoster={participantRoster}
          />

          <div className="meeting-controls">
            {visibleRemoteParticipants.length > 0 && !isRemoteAudioEnabled && (
              <button
                className="control-btn off"
                type="button"
                onClick={enableRemoteAudioPlayback}
              >
                🔈 Zapnúť zvuk účastníkov
              </button>
            )}
            <button
              className={`control-btn ${isMicOn ? 'on' : 'off'}`}
              onClick={handleToggleMic}
              disabled={!hasMicDevice}
              title={hasMicDevice ? '' : 'Mikrofón nie je dostupný na tomto zariadení'}
            >
              {isMicOn ? '🔇 Stlmiť mikrofón' : '🎤 Zapnúť mikrofón'}
            </button>
            <button
              className={`control-btn ${isCameraOn ? 'on' : 'off'}`}
              onClick={handleToggleCamera}
              disabled={!hasCameraDevice}
              title={hasCameraDevice ? '' : 'Kamera nie je dostupná na tomto zariadení'}
            >
              {isCameraOn ? '📷 Vypnúť kameru' : '📹 Zapnúť kameru'}
            </button>
            <button
              className={`control-btn ${isScreenSharing ? 'off' : 'on'}`}
              onClick={handleToggleScreenShare}
            >
              {isScreenSharing ? '🛑 Ukončiť zdieľanie' : '🖥️ Zdieľať obrazovku'}
            </button>
            <button className="control-btn on" type="button" onClick={refreshLocalMedia}>
              🔄 Obnoviť kameru / mikrofón
            </button>
          </div>
        </>
      </div>

      {showHostLeaveDialog && (
        <div className="meeting-modal-overlay" role="presentation">
          <div className="meeting-modal" role="dialog" aria-modal="true" aria-label="Možnosti odchodu hosta">
            <h3>Odchod hosta z meetingu</h3>
            <p>
              Vyber, čo chceš spraviť. Môžeš ukončiť meeting pre všetkých alebo odísť len ty a host rola sa
              automaticky presunie na ďalšieho účastníka.
            </p>
            <div className="meeting-modal-actions">
              <button
                type="button"
                className="control-btn off"
                disabled={isLeaving}
                onClick={() => {
                  setShowHostLeaveDialog(false);
                  executeLeave(true);
                }}
              >
                🛑 Ukončiť meeting pre všetkých
              </button>
              <button
                type="button"
                className="control-btn on"
                disabled={isLeaving}
                onClick={() => {
                  setShowHostLeaveDialog(false);
                  executeLeave(false);
                }}
              >
                🚪 Odísť iba ja
              </button>
              <button
                type="button"
                className="control-btn"
                disabled={isLeaving}
                onClick={() => setShowHostLeaveDialog(false)}
              >
                Zrušiť
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default MeetingRoom;
